    demand_endpoints: Vec<(usize, usize)>,
    representative_nodes: Vec<bool>,
}

#[derive(Clone)]
enum DemandLookup {
    Dense { num_nodes: usize, ids: Vec<usize> },
    Sparse(HashMap<(usize, usize), usize>),
}

impl DemandLookup {
    fn from_map(num_nodes: usize, demand_map: &HashMap<(usize, usize), usize>) -> Self {
        const MAX_DENSE_LOOKUP_BYTES: usize = 96 * 1024 * 1024;
        let max_dense_entries = MAX_DENSE_LOOKUP_BYTES / std::mem::size_of::<usize>();
        let density_limit = demand_map.len().saturating_mul(8).max(1_000_000);

        if let Some(lookup_len) = num_nodes.checked_mul(num_nodes) {
            if lookup_len <= max_dense_entries && lookup_len <= density_limit {
                let mut ids = vec![usize::MAX; lookup_len];
                for (&(src, dst), &demand_id) in demand_map {
                    ids[src * num_nodes + dst] = demand_id;
                }
                return Self::Dense { num_nodes, ids };
            }
        }

        Self::Sparse(demand_map.clone())
    }

    fn get(&self, src: usize, dst: usize) -> Option<usize> {
        match self {
            Self::Dense { num_nodes, ids } => {
                let demand_id = ids[src * *num_nodes + dst];
                (demand_id != usize::MAX).then_some(demand_id)
            }
            Self::Sparse(map) => map.get(&(src, dst)).copied(),
        }
    }
}

const NO_SOURCE_GROUP: usize = usize::MAX;
type ByNodeIndex = Vec<Vec<usize>>;

pub(crate) fn prepare_problem(
    problem: &SolverProblem,
    config: &SolverConfig,
) -> Result<PreparedProblem, SolverError> {
    validate_config(config)?;
    if problem.capacities.len() != problem.num_nodes {
        return Err(SolverError::new(format!(
            "capacities length {} does not match num_nodes {}",
            problem.capacities.len(),
            problem.num_nodes
        )));
    }
    let mut capacities = Vec::with_capacity(problem.capacities.len());
    for (node, &cap) in problem.capacities.iter().enumerate() {
        capacities.push(i64::try_from(cap).map_err(|_| {
            SolverError::new(format!("capacity for node {} does not fit in i64", node))
        })?);
    }
    let (source_group_by_node, source_merge_groups) =
        prepare_source_merge_groups(problem.num_nodes, &problem.source_merge_groups)?;
    if let Some(classes) = &problem.demand_merge_classes {
        if classes.len() != problem.demands.len() {
            return Err(SolverError::new(format!(
                "demand_merge_classes length {} must match demands length {}",
                classes.len(),
                problem.demands.len()
            )));
        }
    }

    let mut demand_map = HashMap::<(usize, usize), usize>::new();
    let mut normalized_demands = Vec::with_capacity(problem.demands.len());
    for (demand_id, demand) in problem.demands.iter().enumerate() {
        if demand.src >= problem.num_nodes || demand.dst >= problem.num_nodes {
            return Err(SolverError::new(format!(
                "demand {} endpoint out of range: {} -> {} with num_nodes {}",
                demand_id, demand.src, demand.dst, problem.num_nodes
            )));
        }
        if demand.src == demand.dst {
            return Err(SolverError::new(format!(
                "demand {} has identical src and dst {}",
                demand_id, demand.src
            )));
        }
        if let Some(previous) = demand_map.insert((demand.src, demand.dst), demand_id) {
            return Err(SolverError::new(format!(
                "duplicate directed demand {} -> {} at indices {} and {}",
                demand.src, demand.dst, previous, demand_id
            )));
        }
        let source_group = source_group_by_node[demand.src];
        if source_group == NO_SOURCE_GROUP {
            return Err(SolverError::new(format!(
                "demand {} src {} is not covered by source_merge_groups",
                demand_id, demand.src
            )));
        }
        let src_group = problem
            .demand_merge_classes
            .as_ref()
            .map(|classes| classes[demand_id])
            .unwrap_or(source_group);
        let mut footprint = demand.footprint.clone();
        footprint.sort_unstable();
        footprint.dedup();
        if footprint.is_empty() {
            return Err(SolverError::new(format!(
                "demand {} has an empty footprint",
                demand_id
            )));
        }
        if let Some(&node) = footprint.iter().find(|&&node| node >= problem.num_nodes) {
            return Err(SolverError::new(format!(
                "demand {} footprint node {} out of range for num_nodes {}",
                demand_id, node, problem.num_nodes
            )));
        }
        let mut footprint_words = vec![0u64; words_for_bits(problem.num_nodes)];
        for &node in &footprint {
            set_bit(&mut footprint_words, node);
        }
        normalized_demands.push(NormalizedDemand {
            src: demand.src,
            dst: demand.dst,
            src_group,
            footprint,
            footprint_words,
        });
    }

    let symmetry = match problem.symmetry.as_ref() {
        Some(spec) => Some(prepare_symmetry(
            problem.num_nodes,
            &capacities,
            &normalized_demands,
            &demand_map,
            &source_merge_groups,
            spec,
            config.validate_symmetry,
        )?),
        None => None,
    };

    let demands = normalized_demands
        .into_iter()
        .map(|demand| PreparedDemand {
            src_group: demand.src_group,
            fp_count: demand.footprint.len(),
            footprint_words: demand.footprint_words,
        })
        .collect();

    Ok(PreparedProblem {
        capacities,
        demands,
        source_group_count: problem
            .demand_merge_classes
            .as_ref()
            .and_then(|classes| classes.iter().copied().max().map(|max_class| max_class + 1))
            .unwrap_or(source_merge_groups.len()),
        symmetry,
    })
}

fn validate_config(config: &SolverConfig) -> Result<(), SolverError> {
    if config.group_size_limit == 0 {
        return Err(SolverError::new("group_size_limit must be positive"));
    }
    if config.groups_per_node == 0 {
        return Err(SolverError::new("groups_per_node must be positive"));
    }
    Ok(())
}

fn prepare_source_merge_groups(
    num_nodes: usize,
    source_merge_groups: &[Vec<usize>],
) -> Result<(Vec<usize>, Vec<Vec<usize>>), SolverError> {
    let mut source_group_by_node = vec![NO_SOURCE_GROUP; num_nodes];
    let mut normalized_groups = Vec::with_capacity(source_merge_groups.len());

    for (group_id, group) in source_merge_groups.iter().enumerate() {
        if group.is_empty() {
            return Err(SolverError::new(format!(
                "source_merge_groups[{}] must not be empty",
                group_id
            )));
        }
        for &node in group {
            if node >= num_nodes {
                return Err(SolverError::new(format!(
                    "source_merge_groups[{}] node {} out of range for num_nodes {}",
                    group_id, node, num_nodes
                )));
            }
            if source_group_by_node[node] != NO_SOURCE_GROUP {
                return Err(SolverError::new(format!(
                    "source_merge_groups node {} appears more than once",
                    node
                )));
            }
            source_group_by_node[node] = group_id;
        }

        let mut normalized = group.clone();
        normalized.sort_unstable();
        normalized_groups.push(normalized);
    }

    Ok((source_group_by_node, normalized_groups))
}

fn prepare_symmetry(
    num_nodes: usize,
    capacities: &[i64],
    demands: &[NormalizedDemand],
    demand_map: &HashMap<(usize, usize), usize>,
    source_merge_groups: &[Vec<usize>],
    spec: &SymmetrySpec,
    validate_closure: bool,
) -> Result<SymmetryRuntime, SolverError> {
    let demand_lookup = DemandLookup::from_map(num_nodes, demand_map);
    let demand_endpoints = demands
        .iter()
        .map(|demand| (demand.src, demand.dst))
        .collect::<Vec<_>>();

    if spec.cyclic_groups.is_empty() {
        return Ok(SymmetryRuntime {
            permutations: vec![(0..num_nodes).collect()],
            demand_lookup,
            demand_endpoints,
            representative_nodes: vec![true; num_nodes],
        });
    }
    if spec.cyclic_groups.len() < 2 {
        return Err(SolverError::new(
            "symmetry cyclic_groups must contain at least two groups",
        ));
    }
    let width = spec.cyclic_groups[0].len();
    if width == 0 {
        return Err(SolverError::new("symmetry groups must not be empty"));
    }
    let mut seen_nodes = vec![false; num_nodes];
    for (row, group) in spec.cyclic_groups.iter().enumerate() {
        if group.len() != width {
            return Err(SolverError::new(format!(
                "symmetry group {} has length {}, expected {}",
                row,
                group.len(),
                width
            )));
        }
        for &node in group {
            if node >= num_nodes {
                return Err(SolverError::new(format!(
                    "symmetry node {} out of range for num_nodes {}",
                    node, num_nodes
                )));
            }
            if seen_nodes[node] {
                return Err(SolverError::new(format!(
                    "symmetry node {} appears more than once",
                    node
                )));
            }
            seen_nodes[node] = true;
        }
    }

    for col in 0..width {
        let first = spec.cyclic_groups[0][col];
        for row in 1..spec.cyclic_groups.len() {
            let node = spec.cyclic_groups[row][col];
            if capacities[node] != capacities[first] {
                return Err(SolverError::new(format!(
                    "capacity is not symmetric for nodes {} and {}",
                    first, node
                )));
            }
        }
    }

    let shift_count = spec.cyclic_groups.len();
    let mut permutations = Vec::with_capacity(shift_count);
    for shift in 0..shift_count {
        let mut perm = (0..num_nodes).collect::<Vec<_>>();
        for row in 0..shift_count {
            let shifted_row = (row + shift) % shift_count;
            for col in 0..width {
                perm[spec.cyclic_groups[row][col]] = spec.cyclic_groups[shifted_row][col];
            }
        }
        permutations.push(perm);
    }

    let mut representative_nodes = vec![true; num_nodes];
    for row in 1..shift_count {
        for &node in &spec.cyclic_groups[row] {
            representative_nodes[node] = false;
        }
    }

    if validate_closure {
        let generator_shift = 1;
        let perm = &permutations[generator_shift];
        validate_source_merge_group_closure(source_merge_groups, perm)?;
        for (demand_id, demand) in demands.iter().enumerate() {
            let shifted_src = perm[demand.src];
            let shifted_dst = perm[demand.dst];
            let Some(shifted_id) = demand_lookup.get(shifted_src, shifted_dst) else {
                return Err(SolverError::new(format!(
                    "symmetry generator maps demand {} ({} -> {}) to missing demand {} -> {}",
                    demand_id, demand.src, demand.dst, shifted_src, shifted_dst
                )));
            };
            let mut shifted_footprint = demand
                .footprint
                .iter()
                .map(|&node| perm[node])
                .collect::<Vec<_>>();
            shifted_footprint.sort_unstable();
            shifted_footprint.dedup();
            if shifted_footprint != demands[shifted_id].footprint {
                return Err(SolverError::new(format!(
                    "symmetry generator maps demand {} footprint to a different footprint for demand {}",
                    demand_id, shifted_id
                )));
            }
        }
    }

    Ok(SymmetryRuntime {
        permutations,
        demand_lookup,
        demand_endpoints,
        representative_nodes,
    })
}

fn validate_source_merge_group_closure(
    source_merge_groups: &[Vec<usize>],
    perm: &[usize],
) -> Result<(), SolverError> {
    let mut group_index = HashMap::<Vec<usize>, usize>::with_capacity(source_merge_groups.len());
    for (group_id, group) in source_merge_groups.iter().enumerate() {
        group_index.insert(group.clone(), group_id);
    }

    let mut shifted = Vec::new();
    for (group_id, group) in source_merge_groups.iter().enumerate() {
        shifted.clear();
        shifted.extend(group.iter().map(|&node| perm[node]));
        shifted.sort_unstable();
        if !group_index.contains_key(&shifted) {
            return Err(SolverError::new(format!(
                "symmetry generator maps source_merge_groups[{}] to a missing source merge group",
                group_id
            )));
        }
    }
    Ok(())
}

pub(crate) fn init_singletons(
    demands: &[PreparedDemand],
    num_nodes: usize,
    build_members_index: bool,
) -> (
    Vec<Group>,
    Vec<i64>,
    ByNodeIndex,
    Option<HashMap<Vec<usize>, Vec<usize>>>,
) {
    let mut groups = Vec::with_capacity(demands.len());
    let mut usage = vec![0i64; num_nodes];
    let mut by_node = vec![Vec::new(); num_nodes];
    let mut members_index = if build_members_index {
        Some(HashMap::<Vec<usize>, Vec<usize>>::with_capacity(
            demands.len(),
        ))
    } else {
        None
    };

    for (demand_id, demand) in demands.iter().enumerate() {
        let gid = groups.len();
        for node in bit_iter(&demand.footprint_words).filter(|&node| node < num_nodes) {
            usage[node] += 1;
            by_node[node].push(gid);
        }
        let members = vec![demand_id];
        if let Some(index) = members_index.as_mut() {
            index.entry(members.clone()).or_default().push(gid);
        }
        groups.push(Group {
            src_group: demand.src_group,
            size: 1,
            fp_count: demand.fp_count,
            footprint: demand.footprint_words.clone(),
            members,
            active: true,
        });
    }

    (groups, usage, by_node, members_index)
}

fn rebuild_index(groups: &[Group], num_nodes: usize) -> ByNodeIndex {
    let mut by_node = vec![Vec::new(); num_nodes];
    for (gid, group) in groups.iter().enumerate() {
        if !group.active {
            continue;
        }
        for node in bit_iter(&group.footprint).filter(|&node| node < num_nodes) {
            by_node[node].push(gid);
        }
    }
    by_node
}

pub(crate) fn apply_merge(
    groups: &mut Vec<Group>,
    usage: &mut [i64],
    by_node: &mut [Vec<usize>],
    i: usize,
    j: usize,
) -> usize {
    let num_nodes = usage.len();
    let (src_group, new_footprint, members) = {
        let group_i = &groups[i];
        let group_j = &groups[j];
        debug_assert_eq!(group_i.src_group, group_j.src_group);
        let src_group = group_i.src_group;
        for node in bit_iter(&group_i.footprint).filter(|&node| node < num_nodes) {
            usage[node] -= 1;
        }
        for node in bit_iter(&group_j.footprint).filter(|&node| node < num_nodes) {
            usage[node] -= 1;
        }

        let new_footprint = union_words(&group_i.footprint, &group_j.footprint);
        let mut members = Vec::with_capacity(group_i.members.len() + group_j.members.len());
        members.extend_from_slice(&group_i.members);
        members.extend_from_slice(&group_j.members);
        members.sort_unstable();
        (src_group, new_footprint, members)
    };

    groups[i].active = false;
    groups[j].active = false;

    let new_gid = groups.len();
    for node in bit_iter(&new_footprint).filter(|&node| node < num_nodes) {
        usage[node] += 1;
        by_node[node].push(new_gid);
    }
    groups.push(Group {
        src_group,
        size: members.len(),
        fp_count: count_bits(&new_footprint),
        footprint: new_footprint,
        members,
        active: true,
    });
    new_gid
}

pub(crate) fn validate_usage(groups: &[Group], num_nodes: usize) -> Vec<i64> {
    let mut usage = vec![0i64; num_nodes];
    for group in groups.iter().filter(|group| group.active) {
        for node in bit_iter(&group.footprint).filter(|&node| node < num_nodes) {
            usage[node] += 1;
        }
    }
    usage
}

pub(crate) fn words_for_bits(bits: usize) -> usize {
    (bits + 63) / 64
}

pub(crate) fn set_bit(words: &mut [u64], bit: usize) {
    words[bit / 64] |= 1u64 << (bit % 64);
}

pub(crate) fn count_bits(words: &[u64]) -> usize {
    words.iter().map(|word| word.count_ones() as usize).sum()
}

pub(crate) fn union_words(a: &[u64], b: &[u64]) -> Vec<u64> {
    a.iter().zip(b.iter()).map(|(x, y)| x | y).collect()
}

pub(crate) fn bit_iter(words: &[u64]) -> BitIter<'_> {
    BitIter {
        words,
        word_idx: 0,
        word: words.first().copied().unwrap_or(0),
    }
}

pub(crate) struct BitIter<'a> {
    words: &'a [u64],
    word_idx: usize,
    word: u64,
}

impl Iterator for BitIter<'_> {
    type Item = usize;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            if self.word != 0 {
                let bit = self.word.trailing_zeros() as usize;
                self.word &= self.word - 1;
                return Some(self.word_idx * 64 + bit);
            }
            self.word_idx += 1;
            if self.word_idx >= self.words.len() {
                return None;
            }
            self.word = self.words[self.word_idx];
        }
    }
}

fn total_overflow_i64(usage: &[i64], caps: &[i64]) -> i64 {
    usage
        .iter()
        .zip(caps.iter())
        .map(|(u, c)| (u - c).max(0))
        .sum()
}

fn max_overflow_i64(usage: &[i64], caps: &[i64]) -> i64 {
    usage
        .iter()
        .zip(caps.iter())
        .map(|(u, c)| (u - c).max(0))
        .max()
        .unwrap_or(0)
}

pub fn total_overflow(usage: &[usize], caps: &[usize]) -> usize {
    usage
        .iter()
        .zip(caps.iter())
        .map(|(u, c)| u.saturating_sub(*c))
        .sum()
}

pub fn max_overflow(usage: &[usize], caps: &[usize]) -> usize {
    usage
        .iter()
        .zip(caps.iter())
        .map(|(u, c)| u.saturating_sub(*c))
        .max()
        .unwrap_or(0)
}

pub fn usage_counts(usage: &[usize]) -> BTreeMap<usize, usize> {
    let mut counts = BTreeMap::new();
    for &value in usage {
        *counts.entry(value).or_insert(0) += 1;
    }
    counts
}

pub fn group_size_counts(groups: &[SolverGroup]) -> BTreeMap<usize, usize> {
    let mut counts = BTreeMap::new();
    for group in groups {
        *counts.entry(group.demand_ids.len()).or_insert(0) += 1;
    }
    counts
}

pub fn hottest(usage: &[usize], caps: &[usize], limit: usize) -> Vec<(isize, usize, usize, usize)> {
    let mut items: Vec<_> = usage
        .iter()
        .zip(caps.iter())
        .enumerate()
        .map(|(node, (&u, &c))| (u as isize - c as isize, node, u, c))
        .collect();
    items.sort_unstable_by(|a, b| b.cmp(a));
    items.truncate(limit);
    items
}

pub fn usage_stats(usage: &[usize]) -> (usize, usize, usize, usize, usize) {
    let mut sorted = usage.to_vec();
    sorted.sort_unstable();
    let last = sorted.len().saturating_sub(1);
    let at = |pct: usize| -> usize { sorted[last * pct / 100] };
    (sorted[0], at(50), at(90), at(99), sorted[last])
}

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ClosSourceGroupScope {
    Pod,
    Tor,
}

impl ClosSourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Pod => "pod",
            Self::Tor => "tor",
        }
    }
}

pub fn build_clos(
    k: usize,
    m3: usize,
    tor_cap_override: Option<usize>,
    agg_cap_override: Option<usize>,
    include_intra_pod: bool,
    source_group_scope: ClosSourceGroupScope,
) -> TopologyCase {
    if k < 4 || k % 2 != 0 {
        panic!("--k must be an even integer >= 4");
    }
    let tors_per_pod = k / 2;
    let num_pods = k;
    let num_tors = num_pods * tors_per_pod;
    let num_aggs = num_pods * tors_per_pod;
    let num_nodes = num_tors + num_aggs;
    let tor_cap = tor_cap_override.unwrap_or(m3 * (k * k / 2 + k));
    let agg_cap = agg_cap_override.unwrap_or(m3 * k * k);
    let mut capacities = vec![tor_cap; num_tors];
    capacities.extend(std::iter::repeat(agg_cap).take(num_aggs));

    let tor_pod: Vec<usize> = (0..num_tors).map(|id| id / tors_per_pod).collect();
    let source_merge_groups = match source_group_scope {
        ClosSourceGroupScope::Pod => {
            let mut groups = Vec::with_capacity(num_pods);
            for pod in 0..num_pods {
                let mut group = Vec::with_capacity(tors_per_pod);
                for tor in 0..tors_per_pod {
                    group.push(pod * tors_per_pod + tor);
                }
                groups.push(group);
            }
            groups
        }
        ClosSourceGroupScope::Tor => {
            let mut groups = Vec::with_capacity(num_tors);
            for tor in 0..num_tors {
                groups.push(vec![tor]);
            }
            groups
        }
    };

    let mut demands = Vec::new();
    for src in 0..num_tors {
        let src_pod = tor_pod[src];
        for dst in 0..num_tors {
            let dst_pod = tor_pod[dst];
            if src == dst || (!include_intra_pod && src_pod == dst_pod) {
                continue;
            }
            let footprint_capacity = if src_pod == dst_pod {
                2 + tors_per_pod
            } else {
                2 + 2 * tors_per_pod
            };
            let mut footprint = Vec::with_capacity(footprint_capacity);
            footprint.push(src);
            footprint.push(dst);
            if src_pod == dst_pod {
                for agg in 0..tors_per_pod {
                    footprint.push(num_tors + src_pod * tors_per_pod + agg);
                }
            } else {
                for agg in 0..tors_per_pod {
                    footprint.push(num_tors + src_pod * tors_per_pod + agg);
                    footprint.push(num_tors + dst_pod * tors_per_pod + agg);
                }
            }
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
        }
    }

    let mut cyclic_groups = Vec::with_capacity(num_pods);
    for pod in 0..num_pods {
        let mut group = Vec::with_capacity(2 * tors_per_pod);
        for tor in 0..tors_per_pod {
            group.push(pod * tors_per_pod + tor);
        }
        for agg in 0..tors_per_pod {
            group.push(num_tors + pod * tors_per_pod + agg);
        }
        cyclic_groups.push(group);
    }

    TopologyCase {
        name: format!("clos-k{}", k),
        problem: SolverProblem {
            num_nodes,
            capacities,
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Clos {
            k,
            num_tors,
            num_aggs,
            tors_per_pod,
            tor_cap,
            agg_cap,
            include_intra_pod,
            source_group_scope,
        },
    }
}


use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

pub fn build_leaf_spine(leaves: usize, spines: usize, leaf_cap: usize) -> TopologyCase {
    if leaves < 2 {
        panic!("--leaves must be at least 2");
    }
    if spines == 0 {
        panic!("--spines must be positive");
    }

    let num_nodes = leaves + spines;
    let mut capacities = vec![leaf_cap; leaves];
    capacities.extend(std::iter::repeat(0).take(spines));

    let mut demands = Vec::with_capacity(leaves * (leaves - 1));
    for src in 0..leaves {
        for dst in 0..leaves {
            if src == dst {
                continue;
            }
            demands.push(Demand {
                src,
                dst,
                footprint: vec![src, dst],
            });
        }
    }

    let cyclic_groups = (0..leaves).map(|leaf| vec![leaf]).collect::<Vec<_>>();
    let source_merge_groups = cyclic_groups.clone();

    TopologyCase {
        name: format!("leaf-spine-l{}-s{}", leaves, spines),
        problem: SolverProblem {
            num_nodes,
            capacities,
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::LeafSpine {
            leaves,
            spines,
            leaf_cap,
        },
    }
}

use std::collections::BTreeMap;

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Torus2DSourceGroupScope {
    Row,
    Host,
}

impl Torus2DSourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Row => "row",
            Self::Host => "host",
        }
    }
}

pub fn build_torus2d(
    n: usize,
    cap: usize,
    source_group_scope: Torus2DSourceGroupScope,
) -> TopologyCase {
    if n < 3 {
        panic!("--n must be at least 3");
    }

    let num_nodes = n * n;
    let mut demands = Vec::with_capacity(num_nodes * (num_nodes - 1));
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();

    for src in 0..num_nodes {
        let (sx, sy) = node_xy(src, n);
        for dst in 0..num_nodes {
            if src == dst {
                continue;
            }
            let (dx, dy) = node_xy(dst, n);
            let x_paths = axis_shortest_paths(sx, dx, n);
            let y_paths = axis_shortest_paths(sy, dy, n);
            let shortest = x_paths[0].len() + y_paths[0].len() - 2;

            let mut in_footprint = vec![false; num_nodes];
            let mut footprint = Vec::new();
            for x_path in &x_paths {
                for y_path in &y_paths {
                    for &y in y_path {
                        for &x in x_path {
                            let node = node_id(x, y, n);
                            if !in_footprint[node] {
                                in_footprint[node] = true;
                                footprint.push(node);
                            }
                        }
                    }
                }
            }
            footprint.sort_unstable();

            *path_lengths.entry(shortest).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
        }
    }

    let source_merge_groups = match source_group_scope {
        Torus2DSourceGroupScope::Row => {
            let mut groups = Vec::with_capacity(n);
            for y in 0..n {
                let mut group = Vec::with_capacity(n);
                for x in 0..n {
                    group.push(node_id(x, y, n));
                }
                groups.push(group);
            }
            groups
        }
        Torus2DSourceGroupScope::Host => (0..num_nodes).map(|node| vec![node]).collect(),
    };

    let mut cyclic_groups = Vec::with_capacity(n);
    for y in 0..n {
        let mut row = Vec::with_capacity(n);
        for x in 0..n {
            row.push(node_id(x, y, n));
        }
        cyclic_groups.push(row);
    }

    TopologyCase {
        name: format!("torus2d-n{}", n),
        problem: SolverProblem {
            num_nodes,
            capacities: vec![cap; num_nodes],
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Torus2D {
            n,
            cap,
            source_group_scope,
            path_lengths,
            footprint_sizes,
        },
    }
}

fn axis_shortest_paths(src: usize, dst: usize, n: usize) -> Vec<Vec<usize>> {
    let forward = (dst + n - src) % n;
    let backward = (src + n - dst) % n;

    if forward == 0 {
        return vec![vec![src]];
    }
    if forward < backward {
        return vec![axis_path(src, forward, 1, n)];
    }
    if backward < forward {
        return vec![axis_path(src, backward, -1, n)];
    }

    vec![
        axis_path(src, forward, 1, n),
        axis_path(src, backward, -1, n),
    ]
}

fn axis_path(src: usize, steps: usize, dir: isize, n: usize) -> Vec<usize> {
    let mut path = Vec::with_capacity(steps + 1);
    for step in 0..=steps {
        let offset = step as isize * dir;
        path.push(((src as isize + offset).rem_euclid(n as isize)) as usize);
    }
    path
}

fn node_id(x: usize, y: usize, n: usize) -> usize {
    y * n + x
}

fn node_xy(node: usize, n: usize) -> (usize, usize) {
    (node % n, node / n)
}


use std::collections::{BTreeMap, VecDeque};

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Torus3DSourceGroupScope {
    Line,
    Host,
}

impl Torus3DSourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Line => "line",
            Self::Host => "host",
        }
    }
}

pub fn build_torus3d(
    n: usize,
    cap: usize,
    source_group_scope: Torus3DSourceGroupScope,
) -> TopologyCase {
    if n < 3 {
        panic!("--n must be at least 3");
    }

    let num_nodes = n * n * n;
    let adj = build_adjacency(n);
    let mut all_dist = Vec::with_capacity(num_nodes);
    for src in 0..num_nodes {
        all_dist.push(bfs(&adj, src));
    }

    let mut demands = Vec::with_capacity(num_nodes * (num_nodes - 1));
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();
    for src in 0..num_nodes {
        for dst in 0..num_nodes {
            if src == dst {
                continue;
            }
            let shortest = all_dist[src][dst];
            let mut footprint = Vec::new();
            for node in 0..num_nodes {
                if all_dist[src][node] >= 0
                    && all_dist[dst][node] >= 0
                    && all_dist[src][node] + all_dist[dst][node] == shortest
                {
                    footprint.push(node);
                }
            }
            *path_lengths.entry(shortest as usize).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
        }
    }

    let source_merge_groups = match source_group_scope {
        Torus3DSourceGroupScope::Line => {
            let mut groups = Vec::with_capacity(n * n);
            for z in 0..n {
                for y in 0..n {
                    let mut group = Vec::with_capacity(n);
                    for x in 0..n {
                        group.push(node_id(x, y, z, n));
                    }
                    groups.push(group);
                }
            }
            groups
        }
        Torus3DSourceGroupScope::Host => (0..num_nodes).map(|node| vec![node]).collect(),
    };

    let mut cyclic_groups = Vec::with_capacity(n);
    for z in 0..n {
        let mut plane = Vec::with_capacity(n * n);
        for y in 0..n {
            for x in 0..n {
                plane.push(node_id(x, y, z, n));
            }
        }
        cyclic_groups.push(plane);
    }

    TopologyCase {
        name: format!("torus3d-n{}", n),
        problem: SolverProblem {
            num_nodes,
            capacities: vec![cap; num_nodes],
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Torus3D {
            n,
            cap,
            source_group_scope,
            path_lengths,
            footprint_sizes,
        },
    }
}



fn build_adjacency(n: usize) -> Vec<Vec<usize>> {
    let num_nodes = n * n * n;
    let mut adj = vec![Vec::<usize>::new(); num_nodes];
    for z in 0..n {
        for y in 0..n {
            for x in 0..n {
                let u = node_id(x, y, z, n);
                for (dx, dy, dz) in [(1, 0, 0), (0, 1, 0), (0, 0, 1)] {
                    let v = node_id((x + dx) % n, (y + dy) % n, (z + dz) % n, n);
                    adj[u].push(v);
                    adj[v].push(u);
                }
            }
        }
    }
    for neigh in &mut adj {
        neigh.sort_unstable();
        neigh.dedup();
    }
    adj
}

fn node_id(x: usize, y: usize, z: usize, n: usize) -> usize {
    (z * n + y) * n + x
}

fn bfs(adj: &[Vec<usize>], src: usize) -> Vec<i32> {
    let mut dist = vec![-1i32; adj.len()];
    let mut q = VecDeque::new();
    dist[src] = 0;
    q.push_back(src);
    while let Some(node) = q.pop_front() {
        for &next in &adj[node] {
            if dist[next] < 0 {
                dist[next] = dist[node] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

use std::collections::{BTreeMap, HashMap, VecDeque};
use std::time::Instant;

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DragonflySourceGroupScope {
    Group,
    Router,
    SourceTargetGroup,
}

impl DragonflySourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Group => "group",
            Self::Router => "router",
            Self::SourceTargetGroup => "source-target-group",
        }
    }
}

pub fn build_dragonfly(
    groups: usize,
    routers_per_group: usize,
    global_links_per_router: usize,
    cap: Option<usize>,
    capacity_scale: f64,
    group_size_limit: usize,
    build_log_every: usize,
    source_group_scope: DragonflySourceGroupScope,
) -> TopologyCase {
    if groups - 1 != routers_per_group * global_links_per_router {
        panic!(
            "canonical dragonfly requires groups - 1 == routers_per_group * global_links_per_router"
        );
    }
    let num_nodes = groups * routers_per_group;
    let router_group: Vec<usize> = (0..num_nodes).map(|id| id / routers_per_group).collect();
    let adj = build_adjacency(groups, routers_per_group, global_links_per_router);
    let build_start = Instant::now();

    let mut all_dist = Vec::with_capacity(num_nodes);
    for src in 0..num_nodes {
        all_dist.push(bfs(&adj, src));
        if build_log_every > 0 && (src + 1) % build_log_every == 0 {
            println!(
                "build: bfs {}/{} elapsed_s={:.1}",
                src + 1,
                num_nodes,
                build_start.elapsed().as_secs_f64()
            );
        }
    }

    let mut demands = Vec::new();
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();
    for src in 0..num_nodes {
        for dst in 0..num_nodes {
            if src == dst {
                continue;
            }
            let shortest = all_dist[src][dst];
            let mut footprint = Vec::new();
            for node in 0..num_nodes {
                if all_dist[src][node] >= 0
                    && all_dist[dst][node] >= 0
                    && all_dist[src][node] + all_dist[dst][node] == shortest
                {
                    footprint.push(node);
                }
            }
            *path_lengths.entry(shortest as usize).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
            if build_log_every > 0 && demands.len() % build_log_every == 0 {
                println!(
                    "build: footprints {}/{} elapsed_s={:.1}",
                    demands.len(),
                    num_nodes * (num_nodes - 1),
                    build_start.elapsed().as_secs_f64()
                );
            }
        }
    }

    let natural_usage_max;
    let uniform_cap = if let Some(cap) = cap {
        natural_usage_max = None;
        cap
    } else {
        let natural_usage =
            dragonfly_natural_usage(num_nodes, &router_group, &demands, group_size_limit);
        let max_nat = natural_usage.into_iter().max().unwrap_or(0);
        natural_usage_max = Some(max_nat);
        ((max_nat as f64) * capacity_scale).ceil() as usize
    };
    let capacities = vec![uniform_cap; num_nodes];

    let mut cyclic_groups = Vec::with_capacity(groups);
    for group_id in 0..groups {
        let mut group = Vec::with_capacity(routers_per_group);
        for router in 0..routers_per_group {
            group.push(group_id * routers_per_group + router);
        }
        cyclic_groups.push(group);
    }
    let source_merge_groups = match source_group_scope {
        DragonflySourceGroupScope::Group => cyclic_groups.clone(),
        DragonflySourceGroupScope::Router | DragonflySourceGroupScope::SourceTargetGroup => {
            (0..num_nodes).map(|node| vec![node]).collect()
        }
    };
    let demand_merge_classes = match source_group_scope {
        DragonflySourceGroupScope::Group | DragonflySourceGroupScope::Router => None,
        DragonflySourceGroupScope::SourceTargetGroup => Some(
            demands
                .iter()
                .map(|demand| demand.src * groups + router_group[demand.dst])
                .collect(),
        ),
    };

    TopologyCase {
        name: format!(
            "dragonfly-g{}-a{}-h{}",
            groups, routers_per_group, global_links_per_router
        ),
        problem: SolverProblem {
            num_nodes,
            capacities,
            demands,
            source_merge_groups,
            demand_merge_classes,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::Dragonfly {
            groups,
            routers_per_group,
            global_links_per_router,
            path_lengths,
            footprint_sizes,
            uniform_cap,
            natural_usage_max,
            capacity_scale: cap.is_none().then_some(capacity_scale),
            source_group_scope,
        },
    }
}



fn build_adjacency(
    groups: usize,
    routers_per_group: usize,
    global_links_per_router: usize,
) -> Vec<Vec<usize>> {
    let num_nodes = groups * routers_per_group;
    let mut adj = vec![Vec::<usize>::new(); num_nodes];
    let rid = |group: usize, idx: usize| -> usize { group * routers_per_group + idx };
    let endpoint_idx = |delta: usize| -> usize { (delta - 1) / global_links_per_router };

    for group in 0..groups {
        for i in 0..routers_per_group {
            for j in (i + 1)..routers_per_group {
                let u = rid(group, i);
                let v = rid(group, j);
                adj[u].push(v);
                adj[v].push(u);
            }
        }
    }

    for g1 in 0..groups {
        for g2 in (g1 + 1)..groups {
            let delta = (g2 + groups - g1) % groups;
            let reverse_delta = groups - delta;
            let i1 = endpoint_idx(delta);
            let i2 = endpoint_idx(reverse_delta);
            let u = rid(g1, i1);
            let v = rid(g2, i2);
            adj[u].push(v);
            adj[v].push(u);
        }
    }

    for neigh in &mut adj {
        neigh.sort_unstable();
        neigh.dedup();
    }
    adj
}

fn bfs(adj: &[Vec<usize>], src: usize) -> Vec<i32> {
    let mut dist = vec![-1i32; adj.len()];
    let mut q = VecDeque::new();
    dist[src] = 0;
    q.push_back(src);
    while let Some(node) = q.pop_front() {
        for &next in &adj[node] {
            if dist[next] < 0 {
                dist[next] = dist[node] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

fn dragonfly_natural_usage(
    num_nodes: usize,
    router_group: &[usize],
    demands: &[Demand],
    group_size_limit: usize,
) -> Vec<usize> {
    let mut by_key = HashMap::<(usize, usize), Vec<usize>>::new();
    for (demand_id, demand) in demands.iter().enumerate() {
        by_key
            .entry((demand.src, router_group[demand.dst]))
            .or_default()
            .push(demand_id);
    }

    let mut usage = vec![0usize; num_nodes];
    for demand_ids in by_key.values() {
        let c = ceil_div(demand_ids.len(), group_size_limit);
        let mut footprint = vec![false; num_nodes];
        for &demand_id in demand_ids {
            for &node in &demands[demand_id].footprint {
                footprint[node] = true;
            }
        }
        for (node, used) in footprint.into_iter().enumerate() {
            if used {
                usage[node] += c;
            }
        }
    }
    usage
}

fn ceil_div(n: usize, d: usize) -> usize {
    ((n + d - 1) / d).max(1)
}

use std::collections::{BTreeMap, VecDeque};
use std::time::Instant;

use crate::solver::{Demand, SolverProblem, SymmetrySpec};

use super::{TopologyCase, TopologyMeta};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DragonflyPlusSourceGroupScope {
    Group,
    Tor,
}

impl DragonflyPlusSourceGroupScope {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Group => "group",
            Self::Tor => "tor",
        }
    }
}

pub fn build_dragonfly_plus(
    groups: usize,
    leaves_per_group: usize,
    spines_per_group: usize,
    global_links_per_spine: usize,
    dense_global: bool,
    cap: usize,
    build_log_every: usize,
    source_group_scope: DragonflyPlusSourceGroupScope,
) -> TopologyCase {
    if groups < 2 {
        panic!("--groups must be at least 2");
    }
    if leaves_per_group == 0 {
        panic!("--leaves-per-group must be positive");
    }
    if spines_per_group == 0 {
        panic!("--spines-per-group must be positive");
    }
    let global_links_per_spine = if dense_global {
        groups - 1
    } else {
        global_links_per_spine
    };
    if global_links_per_spine == 0 {
        panic!("--global-links-per-spine must be positive");
    }
    if !dense_global && groups - 1 != spines_per_group * global_links_per_spine {
        panic!(
            "canonical dragonfly+ requires groups - 1 == spines_per_group * global_links_per_spine"
        );
    }

    let switches_per_group = leaves_per_group + spines_per_group;
    let leaves = groups * leaves_per_group;
    let spines = groups * spines_per_group;
    let num_nodes = groups * switches_per_group;
    let adj = build_adjacency(
        groups,
        leaves_per_group,
        spines_per_group,
        global_links_per_spine,
        dense_global,
    );
    let build_start = Instant::now();

    let mut leaf_nodes = Vec::with_capacity(leaves);
    for group in 0..groups {
        for leaf in 0..leaves_per_group {
            leaf_nodes.push(leaf_id(group, leaf, switches_per_group));
        }
    }

    let mut all_dist = Vec::with_capacity(num_nodes);
    for src in 0..num_nodes {
        all_dist.push(bfs(&adj, src));
        if build_log_every > 0 && (src + 1) % build_log_every == 0 {
            println!(
                "build: bfs {}/{} elapsed_s={:.1}",
                src + 1,
                num_nodes,
                build_start.elapsed().as_secs_f64()
            );
        }
    }

    let mut demands = Vec::with_capacity(leaves * (leaves - 1));
    let mut path_lengths = BTreeMap::<usize, usize>::new();
    let mut footprint_sizes = BTreeMap::<usize, usize>::new();
    for &src in &leaf_nodes {
        for &dst in &leaf_nodes {
            if src == dst {
                continue;
            }
            let shortest = all_dist[src][dst];
            let mut footprint = Vec::new();
            for node in 0..num_nodes {
                if all_dist[src][node] >= 0
                    && all_dist[dst][node] >= 0
                    && all_dist[src][node] + all_dist[dst][node] == shortest
                {
                    footprint.push(node);
                }
            }
            *path_lengths.entry(shortest as usize).or_insert(0) += 1;
            *footprint_sizes.entry(footprint.len()).or_insert(0) += 1;
            demands.push(Demand {
                src,
                dst,
                footprint,
            });
            if build_log_every > 0 && demands.len() % build_log_every == 0 {
                println!(
                    "build: footprints {}/{} elapsed_s={:.1}",
                    demands.len(),
                    leaves * (leaves - 1),
                    build_start.elapsed().as_secs_f64()
                );
            }
        }
    }

    let mut cyclic_groups = Vec::with_capacity(groups);
    let mut source_merge_groups = match source_group_scope {
        DragonflyPlusSourceGroupScope::Group => Vec::with_capacity(groups),
        DragonflyPlusSourceGroupScope::Tor => Vec::with_capacity(leaves),
    };
    for group in 0..groups {
        let group_start = group * switches_per_group;
        cyclic_groups.push((group_start..group_start + switches_per_group).collect());
        match source_group_scope {
            DragonflyPlusSourceGroupScope::Group => {
                source_merge_groups.push(
                    (0..leaves_per_group)
                        .map(|leaf| leaf_id(group, leaf, switches_per_group))
                        .collect(),
                );
            }
            DragonflyPlusSourceGroupScope::Tor => {
                for leaf in 0..leaves_per_group {
                    source_merge_groups.push(vec![leaf_id(group, leaf, switches_per_group)]);
                }
            }
        }
    }

    TopologyCase {
        name: format!(
            "dragonfly-plus{}-g{}-l{}-s{}-h{}",
            if dense_global { "-dense" } else { "" },
            groups,
            leaves_per_group,
            spines_per_group,
            global_links_per_spine
        ),
        problem: SolverProblem {
            num_nodes,
            capacities: vec![cap; num_nodes],
            demands,
            source_merge_groups,
            demand_merge_classes: None,
            symmetry: Some(SymmetrySpec { cyclic_groups }),
        },
        meta: TopologyMeta::DragonflyPlus {
            groups,
            leaves_per_group,
            spines_per_group,
            global_links_per_spine,
            dense_global,
            leaves,
            spines,
            cap,
            source_group_scope,
            path_lengths,
            footprint_sizes,
        },
    }
}



fn build_adjacency(
    groups: usize,
    leaves_per_group: usize,
    spines_per_group: usize,
    global_links_per_spine: usize,
    dense_global: bool,
) -> Vec<Vec<usize>> {
    let switches_per_group = leaves_per_group + spines_per_group;
    let num_nodes = groups * switches_per_group;
    let mut adj = vec![Vec::<usize>::new(); num_nodes];

    for group in 0..groups {
        for leaf in 0..leaves_per_group {
            for spine in 0..spines_per_group {
                add_edge(
                    &mut adj,
                    leaf_id(group, leaf, switches_per_group),
                    spine_id(group, spine, leaves_per_group, switches_per_group),
                );
            }
        }
    }

    if dense_global {
        for g1 in 0..groups {
            for g2 in (g1 + 1)..groups {
                for spine in 0..spines_per_group {
                    add_edge(
                        &mut adj,
                        spine_id(g1, spine, leaves_per_group, switches_per_group),
                        spine_id(g2, spine, leaves_per_group, switches_per_group),
                    );
                }
            }
        }
    } else {
        for g1 in 0..groups {
            for g2 in (g1 + 1)..groups {
                let delta = (g2 + groups - g1) % groups;
                let reverse_delta = groups - delta;
                let s1 = endpoint_spine(delta, global_links_per_spine);
                let s2 = endpoint_spine(reverse_delta, global_links_per_spine);
                add_edge(
                    &mut adj,
                    spine_id(g1, s1, leaves_per_group, switches_per_group),
                    spine_id(g2, s2, leaves_per_group, switches_per_group),
                );
            }
        }
    }

    for neigh in &mut adj {
        neigh.sort_unstable();
        neigh.dedup();
    }
    adj
}

fn leaf_id(group: usize, leaf: usize, switches_per_group: usize) -> usize {
    group * switches_per_group + leaf
}

fn spine_id(
    group: usize,
    spine: usize,
    leaves_per_group: usize,
    switches_per_group: usize,
) -> usize {
    group * switches_per_group + leaves_per_group + spine
}

fn endpoint_spine(delta: usize, global_links_per_spine: usize) -> usize {
    (delta - 1) / global_links_per_spine
}

fn add_edge(adj: &mut [Vec<usize>], u: usize, v: usize) {
    adj[u].push(v);
    adj[v].push(u);
}

fn bfs(adj: &[Vec<usize>], src: usize) -> Vec<i32> {
    let mut dist = vec![-1i32; adj.len()];
    let mut q = VecDeque::new();
    dist[src] = 0;
    q.push_back(src);
    while let Some(node) = q.pop_front() {
        for &next in &adj[node] {
            if dist[next] < 0 {
                dist[next] = dist[node] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

#!/usr/bin/env python3
"""Public executable sanity checks, with per-invocation descendant cleanup."""
import argparse
