#!/usr/bin/env python3
"""Local equivalent of the public checker (no kill-based supervision)."""
import json, math, pathlib, subprocess, sys, time

def pairs(items):
    obj = {}
    for key, val in items:
        if key in obj: raise ValueError('duplicate output key')
        obj[key] = val
    return obj

def nonfinite(value): raise ValueError('nonfinite output')
def finite_float(value):
    parsed = float(value)
    if not math.isfinite(parsed): raise ValueError('nonfinite output')
    return parsed

def strict_load(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs,
                      parse_constant=nonfinite, parse_float=finite_float)

def same(a, b):
    if type(a) is not type(b): return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def run(data, candidate='submission/main.py'):
    start = time.time()
    proc = subprocess.run([sys.executable, '-B', candidate], input=data.encode('utf-8'),
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
    elapsed = time.time() - start
    if proc.returncode != 0:
        raise ValueError('candidate nonzero exit %d: %s' % (proc.returncode, proc.stderr.decode()[:2000]))
    return strict_load(proc.stdout), elapsed, proc.stderr.decode()

def main():
    here = pathlib.Path('/workspace')
    fixtures = json.loads((here/'examples/checks.json').read_text())
    failures = 0
    for i, fixture in enumerate(fixtures):
        data = fixture.get('raw')
        if data is None:
            data = json.dumps(fixture['request'], separators=(',', ':'))
        try:
            result, elapsed, err = run(data)
            ok = same(result, fixture['response'])
            print('fixture %d: %s (%.1fs)' % (i, 'PASS' if ok else 'FAIL', elapsed))
            if not ok:
                failures += 1
                print('  expected:', json.dumps(fixture['response'])[:800])
                print('  actual  :', json.dumps(result)[:800])
            if err.strip(): print('  stderr:', err[:500])
        except Exception as exc:
            failures += 1
            print('fixture %d: ERROR %r' % (i, exc))
    print('failures:', failures)
    return 1 if failures else 0

if __name__ == '__main__':
    raise SystemExit(main())
