"""Independent reference implementation of PROTOCOL.md (slow but literal)."""
import json
from collections import deque


def bfs(adj, src):
    dist = [-1] * len(adj)
    dist[src] = 0
    q = deque([src])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] < 0:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist


class Topology:
    def __init__(self, spec):
