        elif mode in ('torus2d', 'torus3d'):
            n = spec[1]; scope = spec[2]
            dim = 2 if mode == 'torus2d' else 3
            self.n = n ** dim
            adj = [[] for _ in range(self.n)]
            def nid(*coords):
                idx = 0
                for c in coords: idx = idx * n + c
                return idx
            axes = [1, 0, 0], [0, 1, 0], [0, 0, 1]
            for idx in range(self.n):
                coords = []
                rest = idx
                for _ in range(dim):
                    coords.append(rest % n); rest //= n
                coords = coords[::-1]
                for a in range(dim):
                    for sign in (1, -1):
                        nxt = list(coords)
                        nxt[a] = (coords[a] + sign) % n
                        v = nid(*nxt)
                        if v not in adj[idx]:
                            adj[idx].append(v)
            self.adj = adj
            self.cache_nodes = set(range(self.n))
            self.endpoints = list(range(self.n))
            if scope == 'host':
