                        s2 = (g - delta - 1) // h
                        u = spine(g1, s1); v = spine(g2, s2)
                        adj[u].append(v); adj[v].append(u)
            self.adj = adj
            self.cache_nodes = set(range(self.n))
            self.endpoints = []
            for group in range(g):
                for i in range(l):
                    self.endpoints.append(leaf(group, i))
            if scope == 'group':
                self.domain = lambda s, d: s // sw
            else:
                self.domain = lambda s, d: (s // sw) * l + (s % sw)
            for s in self.endpoints:
                for d in self.endpoints:
                    if s != d: self.pairs.append((s, d))
        else:
            raise ValueError('topology')
        # distances and footprints
        dists = [bfs(self.adj, s) for s in range(len(self.adj))]
        self.fp = []
        for (s, d) in self.pairs:
            best = dists[s][d]
            fp = set()
            for v in self.cache_nodes:
                if dists[s][v] >= 0 and dists[d][v] >= 0 and dists[s][v] + dists[d][v] == best:
                    fp.add(v)
            self.fp.append(frozenset(fp))
        self.domains = [self.domain(s, d) for (s, d) in self.pairs]


class State:
    def __init__(self, topo, caps, groups, tasks):
        self.topo = topo
        self.caps = list(caps)
        self.quota = [g[0] for g in groups]
        self.budget = [g[1] for g in groups]
        self.template = [t[0] for t in tasks]
        self.group = [t[1] for t in tasks]
        self.weight = [t[2] for t in tasks]
        self.class_ = [t[3] for t in tasks]
        self.pinned = [t[4] for t in tasks]

    def copy(self):
        s = State.__new__(State)
        s.topo = self.topo
        s.caps = list(self.caps)
        s.quota = list(self.quota); s.budget = list(self.budget)
        s.template = list(self.template); s.group = list(self.group)
        s.weight = list(self.weight); s.class_ = list(self.class_)
        s.pinned = list(self.pinned)
        return s

    def group_members(self):
        out = [[] for _ in self.quota]
        for t, g in enumerate(self.group):
            out[g].append(t)
        return out

    def group_fp(self):
        members = self.group_members()
        fps = []
        for g, ts in enumerate(members):
            fp = set()
            for t in ts:
                fp |= self.topo.fp[self.template[t]]
            fps.append(fp)
        return fps

    def usage(self):
        fps = self.group_fp()
        use = [0] * self.topo.n
        for g, fp in enumerate(fps):
            if not fp: continue
            for node in fp:
                use[node] += self.quota[g]
        return use

    def loads(self):
        load = [0] * len(self.quota)
        for t in range(len(self.group)):
            load[self.group[t]] += self.weight[t]
        return load

    def keys(self):
        members = self.group_members()
        out = []
        for ts in members:
            out.append(set((self.topo.domains[self.template[t]], self.class_[t]) for t in ts))
        return out

    def violations(self):
        topo = self.topo
        use = self.usage()
        cap = sum(1 for n in range(topo.n) if use[n] > self.caps[n])
        keys = self.keys()
        mixed = sum(1 for k in keys if len(k) > 1)
        load = self.loads()
        work = 0
        for g in range(len(self.quota)):
            if len(keys[g]) == 0: continue
            if self.quota[g] == 0 or load[g] > self.quota[g] * self.budget[g]:
                work += 1
        return [cap, mixed, work, 0]

    def certificate(self, query):
        topo = self.topo
        members = self.group_members()
        fps = self.group_fp()
        load = self.loads()
        use = self.usage()
        keys = self.keys()
        active = sum(1 for g in range(len(self.quota)) if members[g])
        slots = sum(use)
        weight = sum(self.weight)
        pins = sum(1 for p in self.pinned if p)
        grows = []
        for g in query['groups']:
            if members[g]:
                k = sorted(keys[g])[0]
                d, c = k
            else:
                d, c = -1, -1
            grows.append([g, len(members[g]), load[g], self.quota[g], self.budget[g], len(fps[g]), d, c])
        nrows = [[n, use[n], self.caps[n]] for n in query['nodes']]
        trows = [[t, self.group[t], self.template[t], self.weight[t], self.class_[t], self.pinned[t]]
                 for t in query['tasks']]
        return {'totals': [active, slots, weight, pins], 'groups': grows, 'nodes': nrows, 'tasks': trows}


def pin_violations(old, new):
    """Count protected tasks violated by a proposal."""
    count = 0
    for t in range(len(old.pinned)):
        if not old.pinned[t]: continue
        if (new.template[t] != old.template[t] or new.group[t] != old.group[t]
                or new.weight[t] != old.weight[t] or new.class_[t] != old.class_[t]):
            count += 1
            continue
        if new.quota[old.group[t]] != old.quota[old.group[t]]:
            count += 1
    return count


def apply_edits(state, edits):
    for edit in edits:
        op = edit[0]
        if op == 'move':
            state.group[edit[1]] = edit[2]
        elif op == 'weight':
            state.weight[edit[1]] = edit[2]
        elif op == 'class':
            state.class_[edit[1]] = edit[2]
        elif op == 'bind':
            state.template[edit[1]] = edit[2]
        elif op == 'pin':
            state.pinned[edit[1]] = edit[2]
        elif op == 'quota':
            state.quota[edit[1]] = edit[2]
        elif op == 'budget':
            state.budget[edit[1]] = edit[2]
        elif op == 'cap':
            state.caps[edit[1]] = edit[2]
        else:
            raise ValueError('edit')


def legal(state):
    v = state.violations()
    return v[0] == 0 and v[1] == 0 and v[2] == 0


def run_session(session):
    topo = Topology(session['topology'])
    state = State(topo, session['caps'], session['groups'], session['tasks'])
    if not legal(state):
        raise ValueError('illegal initial configuration')
    out = {'nodes': topo.n, 'templates': len(topo.pairs),
           'initial': state.certificate(session['query']), 'transactions': []}
    revision = 0
    for tx in session['transactions']:
        if tx['revision'] != revision:
            out['transactions'].append({'accepted': False, 'revision': revision, 'violations': None,
                                        'certificate': state.certificate(tx['query'])})
            continue
        proposal = state.copy()
        apply_edits(proposal, tx['edits'])
        v = proposal.violations()
        v[3] = pin_violations(state, proposal)
        accepted = all(x == 0 for x in v)
        if accepted:
            state = proposal
            revision += 1
        out['transactions'].append({'accepted': accepted, 'revision': revision, 'violations': v,
                                    'certificate': state.certificate(tx['query'])})
    return out


def run(request):
    results = []
    for session in request['sessions']:
        results.append(run_session(session))
    return {'sessions': results}
